-- Restore the unique index that stops the ledger chain forking.
--
-- 20260829100000_ledger_append_only created it in hand-written SQL. The Prisma
-- schema did not know about it, so when 20260829160730_procurement_domain was
-- generated by diffing the schema against the database, the index looked like
-- drift and the generated migration dropped it. Nothing failed loudly: the
-- ledger kept appending, and kept verifying, right up until two entries claimed
-- the same predecessor.
--
-- `prev` is now `@unique` in schema.prisma as well, so a future diff will
-- preserve it instead of removing it again.
CREATE UNIQUE INDEX IF NOT EXISTS "ledger_entry_prev_key" ON "ledger_entry"("prev");
